    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Card text\",\"default\":\"#ffffff\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#111827\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #111827;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #111827;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: \"Geist Sans\", Inter, ui-sans-serif, system-ui, sans-serif;\n        overflow: hidden;\n      }\n      #scene {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n      }\n      #world {\n        position: absolute;\n      }\n      .card {\n        position: absolute;\n        left: 0;\n        top: 0;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        font-weight: 700;\n        border: 2px solid rgba(255, 255, 255, 0.1);\n        box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"scrolling-columns\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#111827\"></div>\n      <div id=\"scene\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const vmax = view.vmax;\n        bg.style.backgroundColor = vars.background;\n        const sceneEl = document.getElementById(\"scene\");\n        const durationInFrames = 300;\n        const columns = [\n          { x: -view.width * 0.3, speed: 4, z: 50 },\n          { x: -view.width * 0.1, speed: 7, z: 0 },\n          { x: view.width * 0.1, speed: 5, z: 100 },\n          { x: view.width * 0.3, speed: 6, z: -50 },\n        ];\n        const itemWidth = view.width * 0.15;\n        const itemHeight = itemWidth * 1.2;\n        const gap = 30 * (view.height / 1080);\n        const cardColors = [\"#ef4444\", \"#f87171\", \"#fca5a5\", \"#3b82f6\", \"#60a5fa\", \"#93c5fd\", \"#10b981\", \"#34d399\", \"#6ee7b7\", \"#f59e0b\", \"#fbbf24\", \"#fcd34d\", \"#8b5cf6\", \"#a78bfa\", \"#c4b5fd\"];\n        const world = document.createElement(\"div\");\n        world.id = \"world\";\n        world.style.width = view.width + \"px\";\n        world.style.height = view.height + \"px\";\n        world.style.left = -view.width / 2 + \"px\";\n        world.style.top = -view.height / 2 + \"px\";\n        const anchor = document.createElement(\"div\");\n        anchor.append(world);\n        const simulator = hyperbits.createParticles({\n          fps: 30,\n          spawners: columns.map(function (column, index) {\n            return {\n              id: \"spawner-\" + index,\n              rate: column.speed / (itemHeight + gap),\n              position: { x: column.x + view.width / 2 - itemWidth / 2, y: -view.height * 0.15, z: column.z },\n              velocity: { x: 0, y: column.speed, z: 0 },\n              lifespan: durationInFrames + 200,\n              startFrame: 150,\n            };\n          }),\n        });\n        const cards = new Map();\n        function cardFor(particle) {\n          let card = cards.get(particle.id);\n          if (card) return card;\n          card = document.createElement(\"div\");\n          card.className = \"card\";\n          const variant = Math.floor(particle.seed * cardColors.length);\n          card.style.width = itemWidth + \"px\";\n          card.style.height = itemHeight + \"px\";\n          card.style.backgroundColor = cardColors[variant];\n          card.style.color = vars.color;\n          card.style.fontSize = itemWidth * 0.2 + \"px\";\n          card.style.borderRadius = itemWidth * 0.05 + \"px\";\n          card.textContent = String((variant % 9) + 1);\n          card.setAttribute(\"data-layout-allow-overlap\", \"\");\n          card.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          card.setAttribute(\"data-layout-allow-overflow\", \"\");\n          world.append(card);\n          cards.set(particle.id, card);\n          return card;\n        }\n        const scene = hyperbits.createScene3D(sceneEl, {\n          perspective: 2000,\n          transitionDuration: durationInFrames / 30,\n          easing: \"easeIn\",\n          steps: [\n            { id: \"start\", x: -view.width * 0.2, y: view.height * 1.5, scale: 0.85, duration: 1 / 30 },\n            { id: \"end\", x: view.width * 0.5, y: view.height * 1.2, scale: 1, duration: durationInFrames / 30 },\n          ],\n          elements: [{ element: anchor, x: 0, y: 0, z: 0 }],\n        });\n        sceneEl.style.position = \"absolute\";\n        sceneEl.style.inset = \"0\";\n        sceneEl.style.zIndex = \"1\";\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        const previousUpdate = timeline.eventCallback(\"onUpdate\");\n        function renderCards() {\n          const active = simulator.stateAt(timeline.time());\n          const seen = new Set();\n          for (const particle of active) {\n            const card = cardFor(particle);\n            seen.add(particle.id);\n            card.style.display = \"flex\";\n            card.style.transform = \"translate3d(\" + particle.position.x + \"px, \" + particle.position.y + \"px, \" + particle.position.z + \"px)\";\n            card.style.opacity = String(particle.opacity);\n          }\n          cards.forEach(function (card, id) {\n            if (!seen.has(id)) card.style.display = \"none\";\n          });\n        }\n        timeline.eventCallback(\"onUpdate\", function () {\n          if (typeof previousUpdate === \"function\") previousUpdate.call(timeline);\n          renderCards();\n        });\n        renderCards();\n        timeline.to({}, { duration: 10 }, 0);\n        registerTimeline(\"scrolling-columns\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
