    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Card color\",\"default\":\"#fcc192\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#111111\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #111111;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #111111;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: \"Geist Sans\", Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #scene {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n      }\n      .card {\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        color: #ffffff;\n        font-weight: 700;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"carousel\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#111111\"></div>\n      <div id=\"scene\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const sceneEl = document.getElementById(\"scene\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        const radius = vmin * 60;\n        const count = 8;\n        const cardWidth = vmin * 40;\n        const cardHeight = vmin * 40;\n        const rotationSpeed = 360 / (30 * 10);\n        const elements = [];\n        for (let index = 0; index < count; index += 1) {\n          const card = document.createElement(\"div\");\n          card.className = \"card\";\n          card.style.width = cardWidth + \"px\";\n          card.style.height = cardHeight + \"px\";\n          card.style.backgroundColor = vars.color;\n          card.style.borderRadius = vmin + \"px\";\n          card.style.fontSize = vmin * 4 + \"px\";\n          card.style.boxShadow = \"0 \" + vmin + \"px \" + vmin * 10 + \"px rgba(0, 0, 0, 0.5)\";\n          card.textContent = String(index + 1);\n          card.setAttribute(\"data-layout-allow-overlap\", \"\");\n          card.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          elements.push({ element: card, centered: true, x: 0, y: 0, z: 0, rotateY: 0, index: index });\n        }\n        function placeCards(time) {\n          const frame = time * 30;\n          const baseRotation = frame * rotationSpeed;\n          for (const item of elements) {\n            const angle = item.index * (360 / count) + baseRotation;\n            const angleRad = (angle * Math.PI) / 180;\n            item.x = Math.sin(angleRad) * radius;\n            item.z = Math.cos(angleRad) * radius;\n            item.rotateY = angle;\n          }\n        }\n        placeCards(0);\n        const scene = hyperbits.createScene3D(sceneEl, {\n          perspective: 1000,\n          transitionDuration: 1,\n          stepDuration: 1,\n          easing: \"easeInOutCubic\",\n          steps: [\n            { id: \"0\", duration: 1 },\n            { id: \"1\", z: -vmin * 100, rotateZ: 180, duration: 1 },\n            { id: \"3\", duration: 8 },\n          ],\n          elements: elements,\n        });\n        sceneEl.style.position = \"absolute\";\n        sceneEl.style.inset = \"0\";\n        sceneEl.style.zIndex = \"1\";\n        const timeline = gsap.timeline({ paused: true });\n        const previousUpdate = timeline.eventCallback(\"onUpdate\");\n        timeline.eventCallback(\"onUpdate\", function () {\n          if (typeof previousUpdate === \"function\") previousUpdate.call(timeline);\n          placeCards(timeline.time());\n        });\n        scene.bind(timeline);\n        timeline.to({}, { duration: 10 }, 0);\n        registerTimeline(\"carousel\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
