    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Top and bottom faces\",\"default\":\"#ec8b49\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#111111\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #111111;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #111111;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: \"Geist Sans\", Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #scene {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n      }\n      .face {\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        box-shadow: 0 0 40px rgba(0, 0, 0, 0.3) inset;\n      }\n      .face h1 {\n        color: #fcc192;\n        font-weight: 700;\n        margin: 0.67em 0;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"cube-navigation\"\n      data-start=\"0\"\n      data-duration=\"16\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"16\" style=\"position:absolute;inset:0;background-color:#111111\"></div>\n      <div id=\"scene\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const sceneEl = document.getElementById(\"scene\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        const size = vmin * 35;\n        const distance = size * 0.8;\n        const faces = [\n          { id: \"front\", color: \"#343331\", title: \"TEXT\", rot: [0, 0, 0], pos: [0, 0, size / 2] },\n          { id: \"right\", color: \"#1c1b1a\", title: \"MOTION\", rot: [0, 90, 90], pos: [size / 2, 0, 0] },\n          { id: \"back\", color: \"#343331\", title: \"PARTICLES\", rot: [0, 180, 180], pos: [0, 0, -size / 2] },\n          { id: \"left\", color: \"#1c1b1a\", title: \"GRADIENTS\", rot: [0, -90, -90], pos: [-size / 2, 0, 0] },\n          { id: \"top\", color: vars.color, title: \"3D\", rot: [90, 0, 0], pos: [0, -size / 2, 0] },\n          { id: \"bottom\", color: vars.color, title: \"BITS\", rot: [-90, 0, 0], pos: [0, size / 2, 0] },\n        ];\n        const elements = faces.map(function (face) {\n          const node = document.createElement(\"div\");\n          node.className = \"face\";\n          node.style.width = size + \"px\";\n          node.style.height = size + \"px\";\n          node.style.background = face.color;\n          node.style.boxShadow = \"0 0 \" + 40 * unit + \"px rgba(0, 0, 0, 0.3) inset\";\n          node.setAttribute(\"data-layout-allow-overlap\", \"\");\n          node.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          const heading = document.createElement(\"h1\");\n          heading.textContent = face.title;\n          heading.style.fontSize = size * 0.15 + \"px\";\n          node.append(heading);\n          return { element: node, centered: true, x: face.pos[0], y: face.pos[1], z: face.pos[2], rotateX: face.rot[0], rotateY: face.rot[1], rotateZ: face.rot[2] };\n        });\n        const isoDist = size * 1.5;\n        const isoOffset = isoDist / Math.sqrt(3);\n        const isoStep = { x: isoOffset, y: -isoOffset, z: isoOffset, rotateX: 35.264, rotateY: 45, rotateZ: 0, rotateOrder: \"yxz\" };\n        const stepDuration = 2;\n        const steps = [Object.assign({ id: \"start\", duration: stepDuration }, isoStep)];\n        faces.forEach(function (face) {\n          let x = face.pos[0];\n          let y = face.pos[1];\n          let z = face.pos[2];\n          const rx = face.rot[0];\n          const ry = face.rot[1];\n          const rz = face.rot[2];\n          if (Math.abs(rx) === 90) y += (rx > 0 ? -1 : 1) * distance;\n          else if (Math.abs(ry) === 90) x += (ry > 0 ? 1 : -1) * distance;\n          else if (Math.abs(ry) === 180) z -= distance;\n          else z += distance;\n          steps.push({ id: \"step-\" + face.id, x: x, y: y, z: z, rotateX: rx, rotateY: ry, rotateZ: rz, duration: stepDuration });\n        });\n        steps.push(Object.assign({ id: \"end\", duration: stepDuration }, isoStep));\n        const scene = hyperbits.createScene3D(sceneEl, {\n          perspective: 2000,\n          transitionDuration: 40 / 30,\n          stepDuration: stepDuration,\n          easing: \"easeInOutCubic\",\n          steps: steps,\n          elements: elements,\n        });\n        sceneEl.style.position = \"absolute\";\n        sceneEl.style.inset = \"0\";\n        sceneEl.style.zIndex = \"1\";\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        timeline.to({}, { duration: 16 }, 0);\n        registerTimeline(\"cube-navigation\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
