    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"words\",\"type\":\"string\",\"label\":\"Words (comma separated)\",\"default\":\"GPT,Claude,PaLM,Gemini,LLaMA,Mistral,Mixtral,Falcon,BLOOM,Kimi,MiniMax,Qwen\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Word color\",\"default\":\"#fcc192\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: \"Geist Sans\", Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #space {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n        overflow: hidden;\n      }\n      .fly {\n        position: absolute;\n        left: 0;\n        top: 0;\n      }\n      .word {\n        display: inline-block;\n        text-align: center;\n        font-weight: 700;\n        white-space: pre;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"flying-through-words\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <div id=\"space\" class=\"clip\" data-start=\"0\" data-duration=\"10\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n                const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        const space = document.getElementById(\"space\");\n        space.style.perspective = (view.width < 500 ? 1000 : 5000) + \"px\";\n        const words = String(vars.words).split(\",\").map(function (part) { return part.trim(); }).filter(Boolean);\n        space.setAttribute(\"aria-label\", vars.words);\n        space.style.color = vars.color;\n        const simulator = hyperbits.createParticles({\n          fps: 30,\n          spawners: [{\n            id: \"spawner-0\",\n            rate: 0.2,\n            area: { width: view.width, height: view.height, depth: -vmin * 50 },\n            position: { x: view.width / 2, y: view.height / 2 },\n            lifespan: 100,\n            velocity: { x: 0, y: 0, z: vmin * 10, varianceZ: vmin * 10 },\n          }],\n        });\n        const nodes = new Map();\n        function nodeFor(particle) {\n          let node = nodes.get(particle.id);\n          if (node) return node;\n          node = document.createElement(\"div\");\n          node.className = \"fly\";\n          node.setAttribute(\"data-layout-allow-overlap\", \"\");\n          node.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          node.setAttribute(\"data-layout-allow-overflow\", \"\");\n          const word = document.createElement(\"span\");\n          word.className = \"word\";\n          word.textContent = words[Math.floor(particle.seed * words.length)];\n          word.style.fontSize = vmin * 10 + \"px\";\n          word.style.color = vars.color;\n          node.append(word);\n          space.append(node);\n          nodes.set(particle.id, { node: node, word: word });\n          return nodes.get(particle.id);\n        }\n        const proxy = { time: 0 };\n        function render() {\n          const frame = Math.round(proxy.time * 30);\n          const active = simulator.stateAt(frame / 30);\n          const seen = new Set();\n          for (const particle of active) {\n            const entry = nodeFor(particle);\n            seen.add(particle.id);\n            const age = frame - particle.birthFrame;\n            const progress = Math.min(1, Math.max(0, age / particle.lifespan));\n            entry.node.style.display = \"block\";\n            entry.node.style.transform = \"translate3d(\" + particle.position.x + \"px, \" + particle.position.y + \"px, \" + particle.position.z + \"px) rotate(\" + particle.rotation + \"deg) scale(\" + particle.scale + \")\";\n            entry.node.style.opacity = String(particle.opacity);\n            entry.word.style.opacity = String(hyperbits.interpolateKeyframes([0, 1, 0.5, 0.2, 0], progress));\n          }\n          nodes.forEach(function (entry, id) {\n            if (!seen.has(id)) entry.node.style.display = \"none\";\n          });\n        }\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: 10, duration: 10, ease: \"none\", onUpdate: render }, 0);\n        render();\n        registerTimeline(\"flying-through-words\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
