    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Vignette tint\",\"default\":\"#000000\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#000000\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #000000;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #000000;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #scene {\n        position: absolute;\n        inset: 0;\n        z-index: 1;\n      }\n      .frame {\n        overflow: hidden;\n      }\n      .frame img {\n        object-fit: cover;\n        display: block;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"ken-burns\"\n      data-start=\"0\"\n      data-duration=\"10\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"10\" style=\"position:absolute;inset:0;background-color:#000000\"></div>\n      <div id=\"scene\"></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const sceneEl = document.getElementById(\"scene\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        bg.setAttribute(\"data-color\", vars.color);\n        const frameWidth = vmin * 177.78;\n        const frameHeight = vmin * 100;\n        const xShift = vmin * 4.63;\n        const yShift = vmin * 5.56;\n        const shots = [\n          { seed: 1, scale: [1.1, 1.4], x: [0, xShift], y: [0, 0] },\n          { seed: 2, scale: [1.3, 1.1], x: [-xShift, 0], y: [0, 0] },\n          { seed: 4, scale: [1.0, 1.2], x: [0, 0], y: [yShift, -yShift] },\n        ];\n        const stepDuration = 100 / 30;\n        const steps = shots.map(function (shot, index) {\n          const frame = document.createElement(\"div\");\n          frame.className = \"frame\";\n          frame.style.width = frameWidth + \"px\";\n          frame.style.height = frameHeight + \"px\";\n          frame.style.opacity = \"0\";\n          frame.setAttribute(\"data-layout-allow-overlap\", \"\");\n          frame.setAttribute(\"data-layout-allow-occlusion\", \"\");\n          const mover = document.createElement(\"div\");\n          mover.style.width = frameWidth + \"px\";\n          mover.style.height = frameHeight + \"px\";\n          const image = document.createElement(\"img\");\n          image.src = \"https://picsum.photos/seed/\" + shot.seed + \"/1920/1080\";\n          image.alt = \"\";\n          image.style.width = frameWidth + \"px\";\n          image.style.height = frameHeight + \"px\";\n          mover.append(image);\n          frame.append(mover);\n          return { id: String(index), x: 0, y: 0, z: -10 * index, duration: stepDuration, element: frame, mover: mover, shot: shot };\n        });\n        const scene = hyperbits.createScene3D(sceneEl, {\n          perspective: 1000,\n          transitionDuration: 2,\n          stepDuration: stepDuration,\n          easing: \"easeInOutCubic\",\n          steps: steps,\n        });\n        sceneEl.style.position = \"absolute\";\n        sceneEl.style.inset = \"0\";\n        sceneEl.style.zIndex = \"1\";\n        const timeline = gsap.timeline({ paused: true });\n        scene.bind(timeline);\n        function stepFade(element, enterTime, exitTime, options) {\n          const enter = options.enter;\n          const exit = options.exit;\n          if (enter) {\n            const target = Object.assign({ duration: enter.duration, ease: \"none\" }, enter.to);\n            timeline.fromTo(element, enter.from, target, enterTime);\n          }\n          if (exit) {\n            const target = Object.assign({ duration: exit.duration, ease: \"none\" }, exit.to);\n            timeline.to(element, target, exitTime);\n          }\n        }\n        steps.forEach(function (step, index) {\n          const enterTime = index * stepDuration;\n          stepFade(step.element, enterTime, enterTime + stepDuration, {\n            enter: { from: { opacity: 0 }, to: { opacity: 1 }, duration: 1 },\n            exit: { to: { opacity: 0 }, duration: 1 },\n          });\n          timeline.fromTo(\n            step.mover,\n            { scale: step.shot.scale[0], x: step.shot.x[0], y: step.shot.y[0] },\n            { scale: step.shot.scale[1], x: step.shot.x[1], y: step.shot.y[1], duration: stepDuration, ease: \"none\" },\n            enterTime,\n          );\n        });\n        timeline.to({}, { duration: 10 }, 0);\n        registerTimeline(\"ken-burns\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
