    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"color\",\"type\":\"color\",\"label\":\"Square color\",\"default\":\"#3b82f6\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#09090b\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1080, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Mono\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-mono@5/files/geist-mono-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #09090b;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1080px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #09090b;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #board {\n        position: relative;\n        z-index: 1;\n        width: 100%;\n        height: 100%;\n        display: flex;\n        flex-direction: column;\n        justify-content: center;\n        color: #e4e4e7;\n        font-family: \"Geist Mono\", \"JetBrains Mono\", ui-monospace, monospace;\n        font-weight: 700;\n        overflow: hidden;\n      }\n      .row {\n        display: flex;\n        align-items: center;\n      }\n      .label {\n        opacity: 0.8;\n        flex-shrink: 0;\n      }\n      .track {\n        flex: 1;\n        position: relative;\n      }\n      .dot {\n        border-radius: 4px;\n        box-shadow: 0 0 10px rgba(59, 130, 246, 0.5);\n      }\n      #caption {\n        position: absolute;\n        opacity: 0.5;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"easings-visualizer\"\n      data-start=\"0\"\n      data-duration=\"3\"\n      data-width=\"1080\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"3\" style=\"position:absolute;inset:0;background-color:#09090b\"></div>\n      <div id=\"board\" class=\"clip\" data-start=\"0\" data-duration=\"3\"><div id=\"caption\">Duration: 60 frames</div></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        const board = document.getElementById(\"board\");\n        const caption = document.getElementById(\"caption\");\n        const easings = [\n          { label: \"linear\", value: hyperbits.Easing.linear },\n          { label: \"easeInQuad\", value: hyperbits.Easing.easeInQuad },\n          { label: \"easeOutQuad\", value: hyperbits.Easing.easeOutQuad },\n          { label: \"easeInOutQuad\", value: hyperbits.Easing.easeInOutQuad },\n          { label: \"easeInCubic\", value: hyperbits.Easing.easeInCubic },\n          { label: \"easeOutCubic\", value: hyperbits.Easing.easeOutCubic },\n          { label: \"easeInOutCubic\", value: hyperbits.Easing.easeInOutCubic },\n          { label: \"spring\", value: hyperbits.Easing.spring },\n          { label: \"steps(5)\", value: hyperbits.steps(5) },\n        ];\n        const labelWidth = Math.max(view.width * 0.2, 120 * unit);\n        const trackWidth = view.width - labelWidth - 40 * unit;\n        const verticalPadding = 40 * unit;\n        const itemHeight = (view.height - verticalPadding * 2) / easings.length;\n        const squareSize = Math.min(itemHeight * 0.6, 40 * unit);\n        const travel = trackWidth - squareSize;\n        board.style.padding = verticalPadding + \"px \" + 20 * unit + \"px\";\n        caption.style.bottom = 10 * unit + \"px\";\n        caption.style.right = 20 * unit + \"px\";\n        caption.style.fontSize = 12 * unit + \"px\";\n        const timeline = gsap.timeline({ paused: true });\n        easings.forEach(function (item, index) {\n          const row = document.createElement(\"div\");\n          row.className = \"row\";\n          row.style.height = itemHeight + \"px\";\n          if (index < easings.length - 1) row.style.borderBottom = unit + \"px solid #27272a\";\n          const label = document.createElement(\"div\");\n          label.className = \"label\";\n          label.textContent = item.label;\n          label.style.width = labelWidth + \"px\";\n          label.style.paddingRight = 10 * unit + \"px\";\n          label.style.fontSize = Math.min(itemHeight * 0.4, 16 * unit) + \"px\";\n          const track = document.createElement(\"div\");\n          track.className = \"track\";\n          const dot = document.createElement(\"div\");\n          dot.className = \"dot\";\n          dot.style.width = squareSize + \"px\";\n          dot.style.height = squareSize + \"px\";\n          dot.style.borderRadius = 4 * unit + \"px\";\n          dot.style.backgroundColor = vars.color;\n          track.append(dot);\n          row.append(label, track);\n          board.insertBefore(row, caption);\n          timeline.fromTo(dot, { x: 0 }, { x: travel, duration: 2, ease: item.value }, 0);\n        });\n        timeline.to({}, { duration: 3 }, 0);\n        registerTimeline(\"easings-visualizer\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
