    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"prefix\",\"type\":\"string\",\"label\":\"Prefix\",\"default\":\"width: \"},{\"id\":\"postfix\",\"type\":\"string\",\"label\":\"Postfix\",\"default\":\"px\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Text color\",\"default\":\"#fcc192\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#100f0f\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <style>\n      @font-face {\n        font-family: \"Geist Sans\";\n        font-weight: 700;\n        src: url(https://cdn.jsdelivr.net/npm/@fontsource/geist-sans@5/files/geist-sans-latin-700-normal.woff2) format(\"woff2\");\n      }\n    </style>\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #100f0f;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #100f0f;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: \"Geist Sans\", Inter, ui-sans-serif, system-ui, sans-serif;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      #counter {\n        display: inline-flex;\n        align-items: center;\n        color: #fcc192;\n        font-weight: 700;\n        font-size: 5vw;\n        white-space: pre;\n        position: relative;\n        z-index: 1;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"basic-counter\"\n      data-start=\"0\"\n      data-duration=\"4\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"4\" style=\"position:absolute;inset:0;background-color:#100f0f\"></div>\n      <div id=\"counter\" class=\"clip\" data-start=\"0\" data-duration=\"4\"><span id=\"prefix\">width: </span><span id=\"value\">0</span><span id=\"postfix\">px</span></div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        bg.style.backgroundColor = vars.background;\n        const counterEl = document.getElementById(\"counter\");\n        const valueEl = document.getElementById(\"value\");\n        document.getElementById(\"prefix\").textContent = vars.prefix;\n        document.getElementById(\"postfix\").textContent = vars.postfix;\n        counterEl.style.color = vars.color;\n        counterEl.style.fontSize = view.vw * 5 + \"px\";\n        counterEl.style.width = 300 * (view.width / 1920) + \"px\";\n        const counter = hyperbits.createCounter(valueEl, { decimals: 0 });\n        const proxy = { progress: 0 };\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, {\n          progress: 1,\n          duration: 4,\n          ease: \"none\",\n          onUpdate: function () {\n            counter.proxy.value = hyperbits.interpolateKeyframes([0, 10, 10, 50, 10], proxy.progress);\n            counter.apply();\n          },\n        }, 0);\n        registerTimeline(\"basic-counter\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
