    "sourceCode": "<!doctype html>\n<html lang=\"en\" data-composition-variables='[{\"id\":\"command\",\"type\":\"string\",\"label\":\"Command\",\"default\":\"npm install remotion-bits\"},{\"id\":\"color\",\"type\":\"color\",\"label\":\"Command color\",\"default\":\"#ce9178\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"Background\",\"default\":\"#1e1e1e\"}]'>\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=1920, height=1080\" />\n    <script src=\"https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js\"></script>\n    <script src=\"hyperbits.iife.js\" data-hyperbits-src=\"https://unpkg.com/hyperbits/dist/hyperbits.iife.js\" data-hyperbits-local=\"../../../dist/hyperbits.iife.js\"></script>\n    <style>\n      :root {\n        --bg: #1e1e1e;\n        --fg: #fcc192;\n        --primary: #ec8b49;\n        --surface-dark: #1c1b1a;\n        --surface-light: #343331;\n      }\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n      html,\n      body {\n        margin: 0;\n        width: 1920px;\n        height: 1080px;\n        overflow: hidden;\n        background-color: #1e1e1e;\n      }\n      #root {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n      }\n      #term {\n        position: relative;\n        z-index: 1;\n        width: 100%;\n        height: 100%;\n        display: flex;\n        align-items: flex-start;\n        justify-content: center;\n        font-family: \"JetBrains Mono\", ui-monospace, monospace;\n        color: #d4d4d4;\n        font-weight: 700;\n        line-height: 1.5;\n      }\n      #column {\n        display: flex;\n        flex-direction: column;\n        width: 100%;\n      }\n      #prompt {\n        display: flex;\n      }\n      #arrow {\n        color: #4ec9b0;\n      }\n      #tilde {\n        color: #569cd6;\n      }\n      #typed {\n        color: #ce9178;\n      }\n      #cursor {\n        display: inline-block;\n      }\n      #output {\n        white-space: pre-wrap;\n      }\n    </style>\n  </head>\n  <body>\n    <div\n      id=\"root\"\n      class=\"clip\"\n      data-composition-id=\"cli-simulation\"\n      data-start=\"0\"\n      data-duration=\"15\"\n      data-width=\"1920\"\n      data-height=\"1080\"\n    >\n      <div id=\"bg\" class=\"clip\" data-start=\"0\" data-duration=\"15\" style=\"position:absolute;inset:0;background-color:#1e1e1e\"></div>\n      <div id=\"term\" class=\"clip\" data-start=\"0\" data-duration=\"15\">\n        <div id=\"column\">\n          <div id=\"prompt\"><span id=\"arrow\">➜</span><span id=\"tilde\">~</span><span id=\"command\"><span id=\"typed\"></span><span id=\"cursor\">|</span></span></div>\n          <div id=\"output\"></div>\n        </div>\n      </div>\n    </div>\n    <script>\n      (function () {\n\n        function bitVars() {\n          if (window.__hyperframes && typeof window.__hyperframes.getVariables === \"function\") {\n            return window.__hyperframes.getVariables();\n          }\n          const raw = document.documentElement.getAttribute(\"data-composition-variables\") || \"[]\";\n          const decls = JSON.parse(raw);\n          const values = {};\n          for (const entry of decls) values[entry.id] = entry.default;\n          return values;\n        }\n        function registerTimeline(compositionId, timeline) {\n          window.__timelines = window.__timelines || {};\n          window.__timelines[compositionId] = timeline;\n          timeline.seek(0);\n        }\n\n\n        const vars = bitVars();\n        const root = document.getElementById(\"root\");\n        const bg = document.getElementById(\"bg\");\n        const view = hyperbits.viewport(root);\n        const vmin = view.vmin;\n        const unit = view.height / 1080;\n        bg.style.backgroundColor = vars.background;\n        const term = document.getElementById(\"term\");\n        const column = document.getElementById(\"column\");\n        const arrow = document.getElementById(\"arrow\");\n        const tilde = document.getElementById(\"tilde\");\n        const commandEl = document.getElementById(\"command\");\n        const typed = document.getElementById(\"typed\");\n        const cursor = document.getElementById(\"cursor\");\n        const output = document.getElementById(\"output\");\n        const command = String(vars.command);\n        commandEl.setAttribute(\"aria-label\", command);\n        typed.style.color = vars.color;\n        term.style.padding = vmin * 10 + \"px\";\n        term.style.fontSize = vmin * 3 + \"px\";\n        column.style.gap = vmin + \"px\";\n        arrow.style.marginRight = vmin * 1.5 + \"px\";\n        tilde.style.marginRight = vmin * 1.5 + \"px\";\n        const commandSpeed = 3;\n        const commandTotal = command.length * commandSpeed + 30;\n        const logs = [\"✔ Package found\\n\", \"✔ Dependencies resolved\\n\", \"✔ Installing...\\n\", \"Done in 1.4s\"];\n        const outputDelay = 90;\n        const outputSpeed = 0.5;\n        const pauseAfterType = 20;\n        const events = [{ frame: 0, text: \"\" }];\n        let floatFrame = 0;\n        let current = \"\";\n        function push() { events.push({ frame: Math.round(floatFrame), text: current }); }\n        logs.forEach(function (str) {\n          for (let index = 0; index < str.length; index += 1) {\n            floatFrame += outputSpeed;\n            current += str[index];\n            push();\n          }\n          floatFrame += pauseAfterType;\n          push();\n        });\n        const proxy = { time: 0 };\n        function render() {\n          const frame = Math.round(proxy.time * 30);\n          const visible = Math.min(command.length, Math.floor(frame / commandSpeed));\n          typed.textContent = command.slice(0, visible);\n          const complete = frame > commandTotal;\n          cursor.style.opacity = !complete && frame % 30 < 15 ? \"1\" : \"0\";\n          const relative = frame - outputDelay;\n          let text = \"\";\n          if (relative >= 0) {\n            let active = 0;\n            for (let index = 0; index < events.length; index += 1) {\n              if (events[index].frame <= relative) active = index; else break;\n            }\n            text = events[active].text;\n          }\n          output.textContent = text;\n        }\n        const timeline = gsap.timeline({ paused: true });\n        timeline.to(proxy, { time: 15, duration: 15, ease: \"none\", onUpdate: render }, 0);\n        render();\n        registerTimeline(\"cli-simulation\", timeline);\n\n      })();\n    </script>\n  </body>\n</html>\n",
